# area: overloads
# hypothesis: a broad str overload listed before a narrower Literal['int'] overload leaves the later overload unreachable and should be flagged, and the call with 'int' is typed str although the runtime returns an int.
from typing import Literal, overload, reveal_type


@overload
def parse(value: str) -> str: ...


@overload
def parse(value: Literal['int']) -> int: ...  # expect-error: overload never matched


@overload
def parse(value: int) -> int: ...


def parse(value: str | int) -> str | int:
    if value == 'int':
        return 0
    return value


reveal_type(parse('int'))  # str (first matching overload)
reveal_type(parse(3))  # int
print(parse('int'), parse(3))
